insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('b81bc74e-540d-5144-890e-92e8860de549', '27281c68-7251-542b-9f58-d8ff923fd458', '3.1.4(a)', 'qualitative analysis of ions on a test-tube scale; processes and techniques needed to identify the following ions in an unknown compound: (i) anions: • CO2(g) (see 2.1.4 c) • SO 42–, by precipitation with Ba • Cl –, Br–, I– (see 3.1.3 g) (ii) cations: NH 4+, by reaction with warm NaOH(aq) forming NH3. 3.2 Physical chemistry This section introduces physical chemistry within the general theme of energy. Learners first learn about the importance of enthalpy changes, their uses and determination from experimental results including enthalpy cycles. This section then investigates the ways in which a change in conditions can affect the rate of a chemical reaction, in terms of activation energy, the Boltzmann distribution and catalysis.', 0, 1.66) on conflict (id) do nothing;
insert into public.topics (id, subject, board, level, syllabus, title, sort_order) values ('e1bc3702-309d-51dd-9bf3-37fe9f6266c4', 'chemistry'::public.subject, 'ocr'::public.board, 'alevel'::public.level, 'H432', '3.2.1 Enthalpy changes', 17) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('61eb8fdb-1d92-5d3e-be82-d8834d09716c', 'e1bc3702-309d-51dd-9bf3-37fe9f6266c4', '3.2.1(a)', 'explanation that some chemical reactions are accompanied by enthalpy changes that are exothermic (∆H, negative) or endothermic (∆H, positive)', 0, 0.82) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('75e10e5b-dd96-57ea-9a74-bb4d1b027f6a', 'e1bc3702-309d-51dd-9bf3-37fe9f6266c4', '3.2.1(b)', 'construction of enthalpy profile diagrams to show the difference in the enthalpy of reactants compared with products', 1, 0.8) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('7b8c84df-1152-5ba8-b14e-3a35c3fff7bd', 'e1bc3702-309d-51dd-9bf3-37fe9f6266c4', '3.2.1(c)', 'qualitative explanation of the term activation energy, including use of enthalpy profile diagrams', 2, 0.74) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('1797bcf0-389b-5144-9b17-3fd447f97304', 'e1bc3702-309d-51dd-9bf3-37fe9f6266c4', '3.2.1(d)', 'explanation and use of the terms: (i) standard conditions and standard states formation, combustion and neutralisation only. (physical states under standard conditions) (ii) enthalpy change of reaction (enthalpy and a stated temperature, 298 K. change associated with a stated equation, ∆rH) (iii) enthalpy change of formation (formation of 1 mol of a compound from its elements, ∆fH) (iv) enthalpy change of combustion (complete combustion of 1 mol of a substance, (v) enthalpy change of neutralisation (formation of 1 mol of water from neutralisation, ∆neutH)', 3, 1.82) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('982b20fb-50ce-5159-adf5-59c5a1d08dd5', 'e1bc3702-309d-51dd-9bf3-37fe9f6266c4', '3.2.1(e)', 'determination of enthalpy changes directly from appropriate experimental results, including use of the relationship: q = mc∆T Bond enthalpies', 4, 0.98) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('8d9091f0-c873-55c6-848e-b48e4008ed9f', 'e1bc3702-309d-51dd-9bf3-37fe9f6266c4', '3.2.1(f)', '(i) explanation of enthalpy (as the breaking of 1 mol of bonds in gaseous molecules) (ii) explanation of exothermic and endothermic reactions in terms of enthalpy changes associated with the breaking and making of chemical bonds (iii) use of average bond enthalpies to calculate enthalpy changes and related quantities (see also 2.2.2 f) Hess'' law and enthalpy cycles', 5, 1.48) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('c3f7931b-e9af-5349-8fdb-3cf79968ff05', 'e1bc3702-309d-51dd-9bf3-37fe9f6266c4', '3.2.1(g)', 'Hess'' law for construction of enthalpy cycles and calculations to determine indirectly: (i) an enthalpy change of reaction from enthalpy changes of combustion (ii) an enthalpy change of reaction from enthalpy changes of formation (iii) enthalpy changes from unfamiliar enthalpy cycles', 6, 1.39) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('d93162d4-c6ac-559b-bb49-c618bf73fdfb', 'e1bc3702-309d-51dd-9bf3-37fe9f6266c4', '3.2.1(h)', 'the techniques and procedures used to determine enthalpy changes directly and indirectly.', 7, 0.73) on conflict (id) do nothing;
insert into public.topics (id, subject, board, level, syllabus, title, sort_order) values ('145f943b-c780-5c7c-a8c4-b90a04b2ddf5', 'chemistry'::public.subject, 'ocr'::public.board, 'alevel'::public.level, 'H432', '3.2.2 Reaction rates', 18) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('2ddf416b-b920-55b8-b8d3-6ad19ff99418', '145f943b-c780-5c7c-a8c4-b90a04b2ddf5', '3.2.2(a)', 'the effect of concentration, including the pressure of gases, on the rate of a reaction, in terms of frequency of collisions', 0, 0.85) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('71d557b4-9cc0-58be-bc6b-3bb12f0ebc0a', '145f943b-c780-5c7c-a8c4-b90a04b2ddf5', '3.2.2(b)', 'calculation of reaction rate from the gradients of graphs measuring how a physical quantity changes with time Catalysts', 1, 0.81) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('5868e4b1-ccf1-5ca1-ac11-628c80df50f1', '145f943b-c780-5c7c-a8c4-b90a04b2ddf5', '3.2.2(c)', 'explanation of the role of a catalyst: (i) in increasing reaction rate without being used up by the overall reaction (ii) in allowing a reaction to proceed via a different route with lower activation energy, as shown by enthalpy profile diagrams', 2, 1.3) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('6ee87d6b-1b94-50c1-bad5-aefc8b6d1bac', '145f943b-c780-5c7c-a8c4-b90a04b2ddf5', '3.2.2(d)', '(i) explanation of heterogeneous catalysts (ii) explanation that catalysts have great economic importance and benefits for increased sustainability by lowering temperatures and reducing energy demand from combustion of fossil fuels with resulting reduction in CO 2 emissions', 3, 1.24) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('467a6eda-cd99-55d1-8cb9-72bec293f93a', '145f943b-c780-5c7c-a8c4-b90a04b2ddf5', '3.2.2(e)', 'the techniques and procedures used to investigate reaction rates including the measurement of mass, gas volumes and time The Boltzmann distribution', 4, 0.85) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('b7ccc4d1-b807-5200-a4f9-949b3bdd5459', '145f943b-c780-5c7c-a8c4-b90a04b2ddf5', '3.2.2(f)', 'qualitative explanation of the Boltzmann distribution and its relationship with activation energy (see also 3.2.1 c)', 5, 0.78) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('7c7a538f-d0e1-57e0-a00d-ca0662e7f639', '145f943b-c780-5c7c-a8c4-b90a04b2ddf5', '3.2.2(g)', 'explanation, using Boltzmann distributions, of the qualitative effect on the proportion of molecules exceeding the activation energy and hence the reaction rate, for: (i) temperature changes (ii) catalytic behaviour (see also 3.2.2 c).', 6, 1.19) on conflict (id) do nothing;
insert into public.topics (id, subject, board, level, syllabus, title, sort_order) values ('222b45ef-b6c9-54ed-adca-41fcf8318f06', 'chemistry'::public.subject, 'ocr'::public.board, 'alevel'::public.level, 'H432', '3.2.3 Chemical equilibrium', 19) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('d1f91737-e833-5be5-a5ac-fad48f754e38', '222b45ef-b6c9-54ed-adca-41fcf8318f06', '3.2.3(a)', 'explanation that a dynamic equilibrium exists in a closed system when the rate of the forward reaction is equal to the rate of the reverse reaction and the concentrations of reactants and products do not change', 0, 1.05) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('862f5b94-4175-50fa-8705-0420a3a66f79', '222b45ef-b6c9-54ed-adca-41fcf8318f06', '3.2.3(b)', 'le Chatelier''s principle and its application for homogeneous equilibria to deduce qualitatively the effect of a change in temperature, pressure or concentration on the position of equilibrium', 1, 0.93) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('6b318cb7-67f7-58dd-b146-b896a21fa3bf', '222b45ef-b6c9-54ed-adca-41fcf8318f06', '3.2.3(c)', 'explanation that a catalyst increases the rate of both forward and reverse reactions in an equilibrium by the same amount resulting in an unchanged position of equilibrium', 2, 0.93) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('4c4417f3-e088-55cc-a9b7-7c809cb1d204', '222b45ef-b6c9-54ed-adca-41fcf8318f06', '3.2.3(d)', 'the techniques and procedures used to investigate changes to the position of equilibrium for changes in concentration and temperature.', 3, 0.82) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('6ca3270e-5851-5dc3-9cbb-bc96fd065b1d', '222b45ef-b6c9-54ed-adca-41fcf8318f06', '3.2.3(e)', 'explanation of the importance to the chemical industry of a compromise between chemical equilibrium and reaction rate in deciding the operational conditions The equilibrium constant, Kc', 4, 0.92) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('19cba72f-1fa6-526d-9104-184b2c848c0b', '222b45ef-b6c9-54ed-adca-41fcf8318f06', '3.2.3(f)', 'expressions for the equilibrium constant, Kc , for homogeneous reactions and calculations of the equilibrium constant, Kc , from provided equilibrium concentrations', 5, 0.86) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('a55df69d-5bdb-5097-babc-ed1e294b00b7', '222b45ef-b6c9-54ed-adca-41fcf8318f06', '3.2.3(g)', 'estimation of the position of equilibrium from the magnitude of Kc. Module4:Coreorganicchemistry This module introduces organic chemistry and its important applications to everyday life, including current environmental concerns associated with sustainability. The module assumes knowledge and understanding of the chemical concepts developed in Module 2: Foundations in chemistry. The module provides learners with a knowledge and understanding of the important chemical ideas that underpin the study of organic chemistry: • nomenclature and formula representation, functional groups, organic reactions and isomerism • aliphatic hydrocarbons • alcohols and haloalkanes • organic practical skills and organic synthesis • instrumental analytical techniques to provide evidence of structural features in molecules. 4.1 Basic concepts and hydrocarbons This section is fundamental to the study of organic chemistry. This section introduces the various types of structures used routinely in organic chemistry, nomenclature, and the important concepts of homologous series,', 6, 1.66) on conflict (id) do nothing;
insert into public.topics (id, subject, board, level, syllabus, title, sort_order) values ('df8bf47d-8bf4-508a-9a1e-f79bf2b7a09b', 'chemistry'::public.subject, 'ocr'::public.board, 'alevel'::public.level, 'H432', '4.1.1 Basic concepts of organic chemistry', 20) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('1c4be608-ca57-560e-9e53-c97d8677a3c7', 'df8bf47d-8bf4-508a-9a1e-f79bf2b7a09b', '4.1.1(a)', 'application of IUPAC rules of nomenclature for systematically naming organic compounds', 0, 0.71) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('cbc49a05-edda-59cc-ae87-09d77a5e6ca8', 'df8bf47d-8bf4-508a-9a1e-f79bf2b7a09b', '4.1.1(b)', 'interpretation and use of the terms: (i) general formula (the simplest algebraic See also 2.1.3 b for empirical formula and molecular formula of a member of a homologous series) e.g. for an alkane: CnH2n+2 (ii) structural formula (the minimal detail Definitions not required. that shows the arrangement of atoms in a molecule) e.g. for butane: CH3CH2CH2CH3 or CH3(CH2)2CH3 (iii) displayed formula (the relative positioning The symbols below will be used for cyclohexane and of atoms and the bonds between them) e.g. for ethanol: H H H C C O H H H (iv) skeletal formula (the simplified organic formula, shown by removing hydrogen atoms from alkyl chains, leaving just a carbon skeleton and associated functional groups) e.g. for butan-2-ol: OH Functional groups', 1, 1.57) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('4329c1cd-cd1b-5c0b-8037-8ebff6455176', 'df8bf47d-8bf4-508a-9a1e-f79bf2b7a09b', '4.1.1(c)', 'interpretation and use of the terms: (i) homologous series (a series of organic R may be used to represent alkyl groups, but also compounds having the same functional group but with each successive member differing by CH 2) (ii) functional group (a group of atoms responsible for the characteristic reactions of a compound) (iii) alkyl group (of formula CH) n 2n+1 (iv) aliphatic (a compound containing carbon and hydrogen joined together in straight chains, branched chains or non-aromatic rings) (v)alicyclic (an aliphatic compound arranged in non-aromatic rings with or without side chains) (vi) aromatic (a compound containing a benzene ring) (vii)saturated (single carbon–carbon bonds only) and unsaturated (the presence of multiple carbon–carbon bonds, including C=C, CC/ and aromatic rings)', 2, 2.0) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('bcf9bf15-cf26-5411-8c4a-f833166be1ad', 'df8bf47d-8bf4-508a-9a1e-f79bf2b7a09b', '4.1.1(d)', 'use of the general formula of a homologous series to predict the formula of any member of the series Isomerism', 3, 0.88) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('f451c937-17eb-5454-847d-34b83b55f8da', 'df8bf47d-8bf4-508a-9a1e-f79bf2b7a09b', '4.1.1(e)', 'explanation of the term structural isomers (compounds with the same molecular formula but different structural formulae) and determination of possible structural formulae of an organic molecule, given its molecular formula Reaction mechanisms', 4, 1.0) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('ec0c488b-63f2-5b52-be89-a5fffe58b2fc', 'df8bf47d-8bf4-508a-9a1e-f79bf2b7a09b', '4.1.1(f)', 'the different types of covalent bond fission: (i) homolytic fission (in terms of atom receiving one electron from the bonded pair, forming two radicals) (ii) heterolytic fission (in terms of one bonding atom receiving both electrons from the bonded pair)', 5, 1.28) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('a38bbc2f-03ec-5c93-8011-3d77e2c8c738', 'df8bf47d-8bf4-508a-9a1e-f79bf2b7a09b', '4.1.1(g)', 'the term radical (a species with an unpaired electron) and use of ''dots'' to represent species that are radicals in mechanisms', 6, 0.85) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('c4f109ee-ce70-554c-942e-8c9835307b82', 'df8bf47d-8bf4-508a-9a1e-f79bf2b7a09b', '4.1.1(h)', 'a ''curly arrow '' described as the movement of an electron pair, showing either heterolytic fission or formation of a covalent bond', 7, 0.86) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('daf32b80-520f-539b-93ce-00dd3d07d8fc', 'df8bf47d-8bf4-508a-9a1e-f79bf2b7a09b', '4.1.1(i)', 'reaction mechanisms, using diagrams, to show clearly the movement of an electron pair with ''curly arrows'' and relevant dipoles.', 8, 0.82) on conflict (id) do nothing;
insert into public.topics (id, subject, board, level, syllabus, title, sort_order) values ('3b81b9a4-7914-5f67-9b0f-c939be88662c', 'chemistry'::public.subject, 'ocr'::public.board, 'alevel'::public.level, 'H432', '4.1.2 Alkanes', 21) on conflict (id) do nothing;
