insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('81446a7e-d142-5b06-930b-445d1e21231b', '3b81b9a4-7914-5f67-9b0f-c939be88662c', '4.1.2(b)', 'explanation of the tetrahedral shape and bond angle around each carbon atom in alkanes in terms of electron pair repulsion (see also 2.2.2 g–h)', 1, 0.89) on conflict (id) do nothing;
