insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('b9eafee7-555d-5098-8891-273ae4d5ee4d', '3b81b9a4-7914-5f67-9b0f-c939be88662c', '4.1.2(e)', 'complete combustion of alkanes, as used in fuels, and the incomplete combustion of alkane fuels in a limited supply of oxygen with the resulting potential dangers from CO', 4, 0.94) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('b51c688e-75ff-5c56-a956-f85c71b92d7c', '3b81b9a4-7914-5f67-9b0f-c939be88662c', '4.1.2(f)', 'the reaction of alkanes with chlorine and bromine by radical substitution using ultraviolet radiation, including a mechanism involving homolytic fission and radical reactions in terms of initiation, propagation and termination (see also 4.1.1 f–g)', 5, 1.02) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('0f543b66-6e70-50c0-a522-a07f3672bf64', '3b81b9a4-7914-5f67-9b0f-c939be88662c', '4.1.2(g)', 'the limitations of radical substitution in synthesis by the formation of a mixture of organic products, in terms of further substitution and reactions at different positions in a carbon chain.', 6, 0.97) on conflict (id) do nothing;
insert into public.topics (id, subject, board, level, syllabus, title, sort_order) values ('6a43d050-f56e-5df8-9d2d-9c71fc0abb49', 'chemistry'::public.subject, 'ocr'::public.board, 'alevel'::public.level, 'H432', '4.1.3 Alkenes', 22) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('e56de244-379d-5362-b9f7-eb8fb11fad97', '6a43d050-f56e-5df8-9d2d-9c71fc0abb49', '4.1.3(a)', 'alkenes as unsaturated hydrocarbons containing a C=C bond comprising a π-bond (sideways overlap of adjacent p-orbitals above and below the bonding C atoms) and a σ-bond (overlap of orbitals directly between the bonding atoms) (see also 4.1.2 a); restricted rotation of the π-bond', 0, 1.31) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('ccb1eb18-72ec-5edd-9744-26a87325d649', '6a43d050-f56e-5df8-9d2d-9c71fc0abb49', '4.1.3(b)', 'explanation of the trigonal planar shape and bond angle around each carbon in the C=C of alkenes in terms of electron pair repulsion (see also 2.2.2 g–h, 4.1.2 b) Stereoisomerism in alkenes', 1, 1.16) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('51b85bb8-88d2-5642-961c-543da363879b', '6a43d050-f56e-5df8-9d2d-9c71fc0abb49', '4.1.3(c)', '(i) explanation of same structural formula but with a different arrangement in space) stereoisomerism, in terms of restricted rotation about a double bond and the requirement for two different groups to be attached to each carbon atom of the C=C group) of E/Z isomerism in which two of the substituent groups attached to each carbon atom of the C=C group are the same) (ii) use of Cahn–Ingold–Prelog (CIP) priority rules to identify the E and Z stereoisomers', 2, 1.55) on conflict (id) do nothing;
insert into public.spec_points (id, topic_id, code, title, sort_order, weight) values ('30a16aee-30ee-5b7c-92d2-e13582c74299', '6a43d050-f56e-5df8-9d2d-9c71fc0abb49', '4.1.3(d)', 'determination of possible E/Z or cis–trans stereoisomers of an organic molecule, given its structural formula Addition reactions of alkenes', 3, 0.82) on conflict (id) do nothing;
